#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("EMPTY");
        return 1;
    }
    if (argc > 2) {
        puts("TOO_MANY");
        return 1;
    }
    char *str1 = argv[1];
    char *str2 = argv[2];
    int len1 = strlen(str1);
    int len2 = strlen(str2);
    int min_len = (len1 < len2) ? len1 : len2;
    if (min_len > 100) {
        puts("TOO_LONG");
        return 1;
    }
    int i;
    for (i = 0; i < min_len; i++) {
        if (str1[i] != str2[i]) {
            break;
        }
    }
    for (int j = 0; j < i; j++) {
        putc(str1[j], stdout);
    }
    putc('\n', stdout);
    return 0;
}
